CString EditorFrame::DocumentName()const{CString name=sessionLabel_;if(name.IsEmpty())name=PathFindFileName((projectPrimary_?projectPath_:path_).GetString());if(name.IsEmpty())name.Format(L"%s %llu",Tr(Text::TemporaryImage),sessionNumber_);return name+(dirty_?L" *":L"");}
void EditorFrame::NotifyWorkspace(){if(workspace_&&::IsWindow(workspace_->GetSafeHwnd()))workspace_->PostMessage(WorkspaceRefresh);else if(GetSafeHwnd())SetWindowText(Caption()+L" - "+DocumentName());}
CPoint EditorFrame::ImageOrigin()const{return {canvas_.left-offsetX_,canvas_.top-offsetY_};}
CRect EditorFrame::ScreenRect(RECT r)const{auto p=ImageOrigin();return {p.x+static_cast<int>(r.left*zoom_),p.y+static_cast<int>(r.top*zoom_),p.x+static_cast<int>(r.right*zoom_),p.y+static_cast<int>(r.bottom*zoom_)};}
