void EditorFrame::ClampViewport()
{
    if(!horizontal_.GetSafeHwnd())return;if(fit_){zoom_=std::clamp(std::min({1.0,static_cast<double>(std::max(1,canvas_.Width()-Px(m_hWnd,24)))/document_.Width(),static_cast<double>(std::max(1,canvas_.Height()-Px(m_hWnd,24)))/document_.Height()}),.01,8.0);offsetX_=offsetY_=0;}
    offsetX_=std::clamp(offsetX_,0,std::max(0,static_cast<int>(document_.Width()*zoom_)-canvas_.Width()));offsetY_=std::clamp(offsetY_,0,std::max(0,static_cast<int>(document_.Height()*zoom_)-canvas_.Height()));
    SCROLLINFO s{sizeof(s),SIF_RANGE|SIF_PAGE|SIF_POS};s.nMin=0;s.nMax=std::max(0,static_cast<int>(document_.Width()*zoom_)-1);s.nPage=std::max(1,canvas_.Width());s.nPos=offsetX_;horizontal_.SetScrollInfo(&s);s.nMax=std::max(0,static_cast<int>(document_.Height()*zoom_)-1);s.nPage=std::max(1,canvas_.Height());s.nPos=offsetY_;vertical_.SetScrollInfo(&s);zoomSlider_.SetPos(static_cast<int>(zoom_*100));CString percent;percent.Format(L"%.0f%%",zoom_*100);int choice=zoomChoice_.FindStringExact(-1,percent);if(choice<0)choice=zoomChoice_.AddString(percent);zoomChoice_.SetCurSel(choice);
}
void EditorFrame::ViewStatus(){if(!status_.GetSafeHwnd())return;CString s;s.Format(L"%d × %d px  |  %.0f%%",document_.Width(),document_.Height(),zoom_*100);if(canvasHandle_>=0||canvasPending_){CString target;target.Format(L"  |  %s %d × %d px",Tr(Text::Canvas),canvasTarget_.cx,canvasTarget_.cy);s+=target;}else if(style_.tool==core::Tool::Crop&&!cropRegion_.IsRectEmpty()){s+=L"  |  ";s+=Tr(Text::CropPendingHelp);}else if(dragging_||!pixelSelection_.IsRectEmpty()){RECT r=!pixelSelection_.IsRectEmpty()?pixelSelection_:draft_.rect;CString v;v.Format(L"  |  %ld × %ld",r.right-r.left,r.bottom-r.top);s+=v;}if(auto* w=dynamic_cast<EditorWorkspace*>(workspace_)){CString ram;ram.Format(Tr(Text::ResourceStatus),w->ResourceBytes()/1048576.);s+=ram;}status_.SetWindowText(s);}
void EditorFrame::ZoomTo(double value,bool fit){const auto before=ImagePoint(canvas_.CenterPoint());fit_=fit;zoom_=std::clamp(value,.01,8.0);offsetX_=static_cast<int>(before.x*zoom_)-canvas_.Width()/2;offsetY_=static_cast<int>(before.y*zoom_)-canvas_.Height()/2;ClampViewport();TextPosition();ViewStatus();InvalidateRect(canvas_,FALSE);}
void EditorFrame::OnZoomChoice(){CString s;zoomChoice_.GetLBText(zoomChoice_.GetCurSel(),s);ZoomTo(_wtoi(s)/100.0);}
void EditorFrame::OnHScroll(UINT code,UINT pos,CScrollBar* bar){if(mosaicSlider_.GetSafeHwnd()&&reinterpret_cast<HWND>(bar?bar->GetSafeHwnd():nullptr)==mosaicSlider_.GetSafeHwnd()){MosaicScroll(code);return;}if(zoomSlider_.GetSafeHwnd()&&reinterpret_cast<HWND>(bar?bar->GetSafeHwnd():nullptr)==zoomSlider_.GetSafeHwnd()){ZoomTo(zoomSlider_.GetPos()/100.0);return;}if(bar&&bar==&horizontal_){SCROLLINFO s{sizeof(s),SIF_ALL};bar->GetScrollInfo(&s);if(code==SB_THUMBTRACK||code==SB_THUMBPOSITION)offsetX_=s.nTrackPos;else if(code==SB_LEFT)offsetX_=s.nMin;else if(code==SB_RIGHT)offsetX_=s.nMax;else if(code==SB_LINELEFT)offsetX_-=20;else if(code==SB_LINERIGHT)offsetX_+=20;else if(code==SB_PAGELEFT)offsetX_-=canvas_.Width();else if(code==SB_PAGERIGHT)offsetX_+=canvas_.Width();ClampViewport();TextPosition();InvalidateRect(canvas_,FALSE);}else CFrameWnd::OnHScroll(code,pos,bar);}
void EditorFrame::OnVScroll(UINT code,UINT pos,CScrollBar* bar){if(bar==&vertical_){SCROLLINFO s{sizeof(s),SIF_ALL};bar->GetScrollInfo(&s);if(code==SB_THUMBTRACK||code==SB_THUMBPOSITION)offsetY_=s.nTrackPos;else if(code==SB_TOP)offsetY_=s.nMin;else if(code==SB_BOTTOM)offsetY_=s.nMax;else if(code==SB_LINEUP)offsetY_-=20;else if(code==SB_LINEDOWN)offsetY_+=20;else if(code==SB_PAGEUP)offsetY_-=canvas_.Height();else if(code==SB_PAGEDOWN)offsetY_+=canvas_.Height();ClampViewport();TextPosition();InvalidateRect(canvas_,FALSE);}else CFrameWnd::OnVScroll(code,pos,bar);}
void EditorFrame::OnToolCommand(UINT id){ChangeTool(id>=EditorToolFirst&&id<=EditorToolLast?static_cast<int>(id-EditorToolFirst):-1);}
void EditorFrame::OnPalette(UINT id){if(id-PaletteFirst<QuickColors().size())SetCurrentColor(QuickColors()[id-PaletteFirst]);}
